// Один элемент — один смысловой раздел Basilik_Policy.pdf.
// Текст хранится здесь намеренно: облачный n8n не видит файлов репозитория, а
// автоматический splitter может смешать соседние разделы или разрезать один раздел.
const chunks = [
  {
    section: 'Бронирование',
    text: `Стол можно забронировать минимум за 2 часа до визита — через Telegram-бота, по телефону или через форму на сайте. Для банкетов от 15 человек бронь нужно оформить заранее, минимум за 3 дня, чтобы кухня успела спланировать закупку и рассадку.

Бронь считается подтверждённой только после ответного сообщения от бота или администратора — сама заявка гостя это ещё не гарантия столика. Для групп от 8 человек требуется предоплата 15 € с человека, которая учитывается при финальном расчёте.

За гостями стол резервируется 15 минут от заявленного времени брони. Если гость опаздывает больше чем на 15 минут, с ним нужно связаться напрямую — до уточнения стол остаётся за ним, но не может резервироваться бесконечно, если ресторан полон.`,
  },
  {
    section: 'Отмена и перенос брони',
    text: `Бесплатная отмена возможна не позднее чем за 3 часа до времени брони. Если отмена приходит позже — для групп от 8 человек предоплата не возвращается, поскольку кухня и стол уже подготовлены под конкретное число гостей.

Перенести бронь на другое время или дату можно без штрафа при уведомлении не позднее чем за 3 часа — это приравнивается к своевременной отмене с одновременным новым бронированием.`,
  },
  {
    section: 'Напоминания и подтверждение визита',
    text: `За 2 часа до брони бот автоматически отправляет гостю напоминание с просьбой подтвердить визит. Если гость не отвечает на напоминание, администратор связывается с ним лично — это снижает долю неявок (no-show), которые исторически составляли до 30% всех броней.`,
  },
  {
    section: 'Банкеты и большие группы',
    text: `Для групп от 15 человек доступно отдельное банкетное меню и закрытая зона зала — детали обсуждаются индивидуально с администратором после первичной заявки через бота. Минимальный чек на банкет и состав меню зависят от количества гостей и даты.

Оплата банкета — предоплата 30% от предварительной суммы заказа не позднее чем за 2 дня до мероприятия, остаток — в день визита любым доступным способом оплаты.`,
  },
  {
    section: 'Детское меню',
    text: `Детское меню доступно в любое время работы ресторана, отдельного бронирования не требует — достаточно указать количество детей при бронировании стола. При необходимости на стол ставится детский стул; чтобы его точно подготовили к приходу гостей, лучше сообщить об этом заранее при бронировании, хотя это не строго обязательно.`,
  },
  {
    section: 'Бизнес-ланч',
    text: `Бизнес-ланч подаётся по будням с 12:00 до 16:00 и включает суп дня, основное блюдо на выбор и напиток за фиксированную цену 28 €. На бизнес-ланч бронирование не требуется — столы в это время выделены под быстрое обслуживание в порядке живой очереди.`,
  },
  {
    section: 'Оплата',
    text: `Принимаются наличные, банковские карты (Visa, Mastercard, Maestro) и оплата через приложения Apple Pay и Google Pay. Разделить счёт на несколько карт можно по запросу у официанта, ограничений по числу карт нет.

Чаевые не включены в счёт по умолчанию и оставляются на усмотрение гостя — наличными или через терминал отдельной операцией.`,
  },
  {
    section: 'Свой алкоголь (corkage)',
    text: `Гости могут принести собственное вино — за это взимается сервисный сбор (corkage fee) 15 € за бутылку, включающий подачу в бокалах и обслуживание. Крепкий алкоголь и пиво со своей стороны в зал приносить нельзя.`,
  },
  {
    section: 'Дресс-код и атмосфера',
    text: `Строгого дресс-кода нет — ожидается опрятный повседневный стиль (smart casual). Специальных требований к одежде для бизнес-ланча или обычного визита не предъявляется, за исключением закрытых банкетов, где формат обсуждается индивидуально с организатором.`,
  },
  {
    section: 'Питомцы',
    text: `Небольшие питомцы допускаются в летнюю террасу на поводке или в переноске. В основном зале ресторана питомцы не допускаются, за исключением собак-проводников.`,
  },
  {
    section: 'Часы работы, адрес и парковка',
    text: `Ristorante Базилик работает ежедневно с 12:00 до 23:00, кухня закрывается за час до закрытия зала. Ресторан расположен в Берлине; отдельной парковки при ресторане нет, но рядом доступна уличная парковка и парковка на близлежащей общественной стоянке.`,
  },
];

return chunks.map((chunk, index) => ({
  json: {
    text: `${chunk.section}\n\n${chunk.text}`,
    section: chunk.section,
    section_order: index + 1,
    source: 'Basilik_Policy.pdf',
    document_version: '2026-08',
    language: 'ru',
  },
}));
